/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Memory layout for the raw image (docs/DESIGN-NOTES.md, M0d).
 *
 * IMAGE: the code window. The image's first byte is at its start and is
 *   the first instruction run (HW-1); the window shows the flash chip from
 *   offset 0x4000, so an image may be up to 1 MiB less 16 KiB (HW-5).
 * Since M7 only the boot code runs from the window (.boot.text: _start,
 *   the stack fill and sb_start); sb_start copies every other instruction
 *   and constant to RAM with the initial data, so nothing reads the window
 *   once main runs, and the flash may be busy erasing or programming
 *   without anything waiting on it (docs/DESIGN-NOTES.md, M7; HW-79). The
 *   image ends before chip offset 0xEA000, where the stock firmware's
 *   user patch region begins (HW-80), so it never overwrites the stock
 *   firmware's saved patches; since M8a the store (store.h) takes chip
 *   offsets 0xFC000 to 0xFEFFF, past that region.
 * RAM: main RAM is 512 KiB from 0x01C00000 on the chip (HW-6). Its top,
 *   from 0x01C7FC00, is not part of RAM here: the block r0 points to at
 *   entry (HW-4) and the SDK's boot and update area are left alone, and
 *   the vector table at 0x01C7FE00 (HW-18) is written only by
 *   firmware/src/irq.c, through __vectors. fwtest has more RAM (HW-7);
 *   this layout uses only what the chip has.
 * The stack area is two stacks (HW-3): main's, on sp, at the top, and the
 *   interrupt stack, on ssp, below it. Each one's lowest word is its guard
 *   (docs/DESIGN-NOTES.md, M1).
 */

OUTPUT_ARCH(pi32v2)
ENTRY(_start)

/* The store (store.h) begins at chip offset 0xFC000, which the window
 * shows at 0x02000000 + 0xFC000 - 0x4000 in fwtest (HW-5). The stock
 * user patch region begins at chip offset 0xEA000 (HW-80). */
STORE_BASE = 0xFC000;
USER_REGION = 0xEA000;

/* Where the image's first byte runs (Phase A1, HW-91): the raw image at
 * the window's start; the package link (tools/build.sh, with
 * --defsym=IMAGE_ORIGIN=0x02000120) where a package's app.bin runs, past
 * the app area's 0x120-byte directory. The same code either way: only the
 * boot code runs from the window, and it addresses the rest by symbols. */
IMAGE_ORIGIN = DEFINED(IMAGE_ORIGIN) ? IMAGE_ORIGIN : 0x02000000;

MEMORY
{
    IMAGE (rx)  : ORIGIN = IMAGE_ORIGIN, LENGTH = 0xEA000 - 0x4000 - (IMAGE_ORIGIN - 0x02000000)   /* to USER_REGION */
    RAM   (rwx) : ORIGIN = 0x01C00000, LENGTH = 0x0007FC00
}

STACK_SIZE = 0x1000;          /* both stacks */
IRQ_STACK_SIZE = 0x800;       /* the lower half: interrupts, on ssp */

SECTIONS
{
    /* Run from the window: only what runs before the copy to RAM. */
    .text : {
        KEEP(*(.text.entry))
        *(.boot.text)
        . = ALIGN(4);
    } > IMAGE

    /* Fixed at the start of RAM so the tests know where it is: the
     * beacon, then (since M3) the input record and (since M4) the audio
     * record, (since M5) the engine's, (since M6a) MIDI's, (since M6b)
     * MIDI out's, (since M7) the store's, (since M8a) the interface's and
     * (since ARP) the arpeggiator's. */
    .beacon (NOLOAD) : {
        __bss_start = .;
        KEEP(*(.beacon))
        KEEP(*(.beacon.input))
        KEEP(*(.beacon.audio))
        KEEP(*(.beacon.fm))
        KEEP(*(.beacon.midi))
        KEEP(*(.beacon.midiout))
        KEEP(*(.beacon.store))
        KEEP(*(.beacon.ui))
        KEEP(*(.beacon.arp))
    } > RAM

    .bss (NOLOAD) : {
        *(.bss .bss.*)
        . = ALIGN(4);
        __bss_end = .;
    } > RAM

    /* Runs from RAM, loaded from the image just after the boot code:
     * since M7 the code and constants (from __ram_code_start to
     * __ram_code_end), then the initialised data, copied together. */
    .data : {
        __data_start = .;
        __ram_code_start = .;
        *(.text .text.*)
        *(.rodata .rodata.*)
        . = ALIGN(4);
        __ram_code_end = .;
        *(.data .data.*)
        . = ALIGN(4);
        __data_end = .;
    } > RAM AT > IMAGE
    __data_load = LOADADDR(.data);

    /* The stack takes the top of RAM and grows down from __stack_top. */
    __stack_top = ORIGIN(RAM) + LENGTH(RAM);
    __stack_limit = __stack_top - STACK_SIZE;
    __irq_stack_top = __stack_limit + IRQ_STACK_SIZE;
    __vectors = 0x01C7FE00;

    ASSERT(ADDR(.beacon) == 0x01C00000, "the beacon must start main RAM")
    ASSERT(sb_input == 0x01C00060, "the input record must follow the beacon (M3)")
    ASSERT(sb_audio == 0x01C00550, "the audio record must follow the input record (M4)")
    ASSERT(sb_fm == 0x01C00590, "the FM engine's record must follow the audio record (M5)")
    ASSERT(sb_midi == 0x01C005D0, "the MIDI record must follow the FM engine's record (M6a)")
    ASSERT(sb_midi_out == 0x01C00734, "the MIDI out record must follow MIDI in's (M6b)")
    ASSERT(sb_store == 0x01C00780, "the store's record must follow MIDI out's (M7)")
    ASSERT(sb_ui == 0x01C00870, "the interface's record must follow the store's (M8a)")
    ASSERT(sb_arp == 0x01C008D0, "the arpeggiator's record must follow the interface's (ARP)")
    ASSERT(__data_end <= __stack_limit, "data and bss run into the stack")
    ASSERT(__stack_top == 0x01C7FC00, "the stack must end below the reserved top of RAM")
    ASSERT(__stack_top % 8 == 0, "the stack must be 8-byte aligned")
    ASSERT(__irq_stack_top % 8 == 0, "the interrupt stack must be 8-byte aligned")
    ASSERT(__vectors == __stack_top + 0x200, "the vector table is HW-18's, above the reserved area")
    ASSERT(sb_irq_stubs_end - sb_irq_stubs == 128 * 2, "crt0.S's stubs must be 2 bytes each")
    ASSERT(STORE_BASE == 0xFC000, "the store begins at store.h's STORE_BASE")
    ASSERT(STORE_BASE >= USER_REGION + 0x12000, "the store keeps out of the stock user patch region")

    /* Debug information: kept in the ELF, never loaded. Every section is
     * placed by name (the build links with --orphan-handling=error). */
    .debug_info     0 : { *(.debug_info) }
    .debug_abbrev   0 : { *(.debug_abbrev) }
    .debug_line     0 : { *(.debug_line) }
    .debug_str      0 : { *(.debug_str) }
    .debug_loc      0 : { *(.debug_loc) }
    .debug_ranges   0 : { *(.debug_ranges) }
    .debug_frame    0 : { *(.debug_frame) }
    .debug_macinfo  0 : { *(.debug_macinfo) }
    .debug_pubnames 0 : { *(.debug_pubnames) }
    .debug_pubtypes 0 : { *(.debug_pubtypes) }

    /DISCARD/ : { *(.comment) }
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Core 1's entry (M5): core 1 starts here in supervisor mode with stack
 * pointers it must not rely on (HW-10), so it sets its own, on a stack of
 * its own, and runs the FM engine's loop (fm_play.c), which never
 * returns. It takes no interrupt: no source is enabled on it (HW-64).
 */

	.text
	.globl	fm_core1_entry
	.type	fm_core1_entry,@function
fm_core1_entry:
	r1 = fm_core1_stack_top
	sp = r1
	ssp = r1
	call	fm_core1_main
	cli
.Lcore1_stop:
	goto	.Lcore1_stop
	.size	fm_core1_entry, .-fm_core1_entry

	.section .bss.fm_core1_stack,"aw",@nobits
	.balign	8
	.globl	fm_core1_stack
fm_core1_stack:
	.space	1024
fm_core1_stack_top:
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * C runtime start: give C its initial memory, then run main. Called from
 * crt0.S on the stack it set up. The symbols come from firmware/app.ld.
 * Since M7 the initial data begins with every instruction and constant
 * but the boot code's, so this runs from the window and copies them to
 * RAM, where main and everything after it run (docs/DESIGN-NOTES.md, M7).
 */

#include "sb.h"

extern u32 __data_load[], __data_start[], __data_end[];
extern u32 __bss_start[], __bss_end[];

void sb_start(void) __attribute__((noreturn, section(".boot.text")));

void sb_start(void)
{
    const u32 *src = __data_load;
    u32 *dst;

    /* Code, constants and initialised data: their bytes sit in the
     * image, after the boot code. */
    for (dst = __data_start; dst < __data_end; dst++)
        *dst = *src++;

    /* Zero-initialised data. fwtest starts with RAM cleared, but a loader
     * on the chip makes no such promise. */
    for (dst = __bss_start; dst < __bss_end; dst++)
        *dst = 0;

    main();
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * The Plaits demo's engine (M4b's platform load test, docs/DESIGN-NOTES.md):
 * Plaits' voice played through our audio and input APIs only (audio.h,
 * input.h), in place of the test instrument. Built as its own image by
 * tools/build.sh build --demo plaits; never part of the firmware.
 *
 * - A key plays a note: the last key pressed sets the pitch (KEY1 is F3, as
 *   in the test instrument; OCT- and OCT+ shift by octaves) and holds
 *   Plaits' trigger high until it is released.
 * - ALGORITHM selects the engine, one detent each, round all 24, from
 *   the chiptune engine (7): the only one soft-float can render within a
 *   block. Any other overloads core 0 with soft-float (underruns, and
 *   main, starved, stops taking input); built with PLAITS_HWFLOAT every
 *   engine fits (docs/DESIGN-NOTES.md, M4b).
 * - KNOB1 to KNOB4 are Plaits' HARMONICS, TIMBRE, MORPH and its envelope's
 *   decay: each starts in the middle, 64 detents from end to end.
 * - MASTER is the volume, its square as in the test instrument.
 *
 * Plaits computes at its own rate (47 872.34 Hz, its tables and filters
 * are made for it); ours is 44 117.647 Hz, so every pitch is raised by
 * 12 log2(47 872.34 / 44 117.647) = 1.414 semitones to sound right. Its
 * time constants (envelopes, filters' corners in Hz) run 7.8% slow.
 */

#include "audio.h"
#include "input.h"
#include "plaits_voice.h"

#define KEY1_NOTE     53
#define OCTAVES       2
#define RATE_OFFSET   1.4140377f   /* semitones, as above */
#define KNOB_SPAN     64           /* detents from 0 to 1 */
#define GAIN_FULL     (1 << 24)
#define FIRST_ENGINE  7            /* chiptune, as above */

static struct plaits_params params;
static int octave;
static u32 held;                    /* the key holding the trigger, or 0 */
static s32 gain;

/* An encoder's position as a parameter from 0 to 1, starting at 0.5. */
static float knob(u32 control)
{
    int d = input_value(control) + KNOB_SPAN / 2;

    if (d < 0)
        d = 0;
    if (d > KNOB_SPAN)
        d = KNOB_SPAN;
    return (float)d / (float)KNOB_SPAN;
}

void plaits_demo_init(void)
{
    plaits_voice_init(0);
    params.note = 48.0f;
    params.lpg_colour = 0.5f;
}

static void events(void)
{
    struct input_event e;

    while (input_read_audio(&e)) {
        if (e.control >= INPUT_KEY1 && e.control <= INPUT_KEY27) {
            if (e.kind == INPUT_PRESS) {
                held = e.control;
                params.note = (float)(KEY1_NOTE + (int)(e.control - INPUT_KEY1) + 12 * octave) + RATE_OFFSET;
                params.trigger = 1;
            } else if (e.kind == INPUT_RELEASE && e.control == held) {
                held = 0;
                params.trigger = 0;
            }
        } else if (e.kind == INPUT_PRESS && e.control == INPUT_OCT_DOWN) {
            octave -= octave > -OCTAVES;
        } else if (e.kind == INPUT_PRESS && e.control == INPUT_OCT_UP) {
            octave += octave < OCTAVES;
        }
    }
}

void plaits_demo_block(s32 *out, u32 frames)
{
    short buf[2 * PLAITS_RENDER];
    int engine, pot;
    u32 n, i;

    events();
    engine = (FIRST_ENGINE + input_value(INPUT_ALGORITHM)) % PLAITS_ENGINES;
    params.engine = engine < 0 ? engine + PLAITS_ENGINES : engine;
    params.harmonics = knob(INPUT_KNOB1);
    params.timbre = knob(INPUT_KNOB2);
    params.morph = knob(INPUT_KNOB3);
    params.decay = knob(INPUT_KNOB4);
    pot = input_value(INPUT_MASTER);
    gain = pot >= 1023 ? GAIN_FULL : pot * pot * 16;

    for (n = 0; n < frames; n += PLAITS_RENDER) {
        u32 k = frames - n < PLAITS_RENDER ? frames - n : PLAITS_RENDER;

        plaits_voice_render(0, &params, buf, k);
        for (i = 0; i < k; i++) {
            /* 16-bit to the output's 24 bits, then the volume. */
            s32 s = (s32)((s64)((s32)buf[2 * i] << 8) * gain >> 24);

            out[2 * (n + i)] = s;
            out[2 * (n + i) + 1] = s;
        }
    }
    sb_audio.engine[0] = (u32)params.engine;
    sb_audio.engine[1] = held;
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Core 1's entry for the Plaits bench (bench.c, docs/DESIGN-NOTES.md,
 * M4b): core 1 starts here in supervisor mode with stack pointers it
 * must not rely on (HW-10), so it sets its own, on a stack of its own,
 * and runs plaits_core1_main, which never returns.
 */

#if defined(PLAITS_BENCH)

	.text
	.globl	plaits_core1_entry
	.type	plaits_core1_entry,@function
plaits_core1_entry:
	r1 = plaits_core1_stack_top
	sp = r1
	ssp = r1
	call	plaits_core1_main
	cli
.Lcore1_stop:
	goto	.Lcore1_stop
	.size	plaits_core1_entry, .-plaits_core1_entry

	.section .bss.plaits_core1_stack,"aw",@nobits
	.balign	8
plaits_core1_stack:
	.space	8192
plaits_core1_stack_top:

#endif

