/* --- Settings (stored as they are by M7) ------------------------------- */

/* Where a controller change goes (docs/DESIGN-NOTES.md, M6a, "The
 * controller map"). M8 adds targets and changes the map; MIDI learn will
 * write it. */
enum {
    MIDI_TO_NONE,
    MIDI_TO_MOD,          /* vibrato depth */
    MIDI_TO_VOLUME,
    MIDI_TO_EXPRESSION,
    MIDI_TO_SUSTAIN,
    MIDI_TO_KNOB1,        /* the engine's four controls, as KNOB1 to KNOB4 */
    MIDI_TO_KNOB2,
    MIDI_TO_KNOB3,
    MIDI_TO_KNOB4,
    MIDI_TARGETS
};

#define MIDI_SETTINGS_VERSION 4u   /* 2 since M6b: MIDI out's three settings; 3 since M8a: the knobs;
                                    * 4 since ARP: the tempo and what MIDI out sends while it runs */
#define MIDI_OMNI             0u     /* channel: receive on every channel */
#define MIDI_CC_ROUTES        16u

struct midi_settings {
    u8 version;           /* MIDI_SETTINGS_VERSION */
    u8 channel;           /* MIDI_OMNI, or 1 to 16 */
    u8 bend_range;        /* semitones each way, 0 to 24 */
    u8 routes;            /* entries of cc[] in use */
    struct {
        u8 cc;            /* 0 to 119 */
        u8 to;            /* MIDI_TO_* */
    } cc[MIDI_CC_ROUTES];
    /* Since M6b (midi_out.h): */
    u8 out_channel;       /* the panel's messages go out on it: 1 to 16 */
    u8 thru;              /* 1: what MIDI in receives is sent out again */
    u8 local;             /* 1: the panel plays the engine; 0: MIDI out only */
    /* Since M8a (version 3; version 2's byte here was always 0): */
    u8 knobs;             /* 0: KNOB1 to KNOB4 are the macros; 1: direct (M5's controls) */
