/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * MIDI out (M6b; docs/DESIGN-NOTES.md, M6b): a queue of messages, and the
 * transmitter that drains it through UART1's transmit side (HW-72 to
 * HW-74). On the FM-1 the bytes reach no socket (HW-67); in the app they
 * reach other programs.
 *
 * - The engine's block callback (audio.h) is the only writer and the only
 *   reader: midi_out_send() queues a message, midi_out_poll() sends what
 *   waits. Nothing else touches the queue or the UART's transmit side, so
 *   there is no lock and nothing ever waits for the wire.
 * - The transmitter starts a transfer (transmit DMA: TXADR, then TXCNT)
 *   only when the last one has gone (CON0 bit 15, HW-73), never while one
 *   runs, and never changes the bytes of one that runs. A transfer takes
 *   whole messages, up to MIDI_OUT_CHUNK bytes; the poll comes once at
 *   the start of each block and once after the block's events, so a
 *   message queued then has its first byte on the wire at once if the
 *   wire is free.
 * - Running status: a channel message leaves out its status byte when it
 *   is the one sent last, as long as the transmitter has not run dry; the
 *   first message after the queue emptied and the wire went quiet always
 *   carries its status (so a receiver plugged in meanwhile is never left
 *   guessing). System common messages end running status; realtime
 *   messages don't.
 * - When the wire can't keep up (the policy, docs/DESIGN-NOTES.md, M6b):
 *   a control change, pitch bend, pressure or program change replaces a
 *   waiting one of the same kind, channel (and controller or note), if no
 *   note, mode or other message waits after it; MIDI_OUT_RESERVE places
 *   are kept for note offs (and all notes off, all sound off); any other
 *   message that finds the rest full is dropped and counted. A note off
 *   that finds even the reserve full drops the newest waiting message
 *   that ends no notes instead. A note on dropped either way has its note
 *   off dropped too, so the far end never holds a note it was not sent
 *   and never misses the end of one it was.
 */

#ifndef MIDI_OUT_H
#define MIDI_OUT_H

#include "sb.h"
#include "midi.h"

#define MIDI_OUT_QUEUE   32u   /* messages; at most 96 bytes, 31 ms of the wire */
#define MIDI_OUT_RESERVE 8u    /* of them, kept for note offs */
#define MIDI_OUT_CHUNK   12u   /* the most bytes one transfer takes (3.8 ms) */

/* Queues a message (struct midi_msg, midi.h: a status and 0 to 2 data
 * bytes). Engine callback only. Returns 1 if it was queued or merged with
 * a waiting one, 0 if the policy dropped it. */
int midi_out_send(const struct midi_msg *m);
/* A channel message on the out channel (midi_settings.out_channel). */
int midi_out_channel(u32 kind, u32 d1, u32 d2);
/* Sends what waits, if the wire is free. Engine callback only. */
void midi_out_poll(void);

/* --- The MIDI out record, after MIDI in's (firmware/app.ld) ------------ */
#define MIDI_OUT_MARKER 0x424F444Du   /* "MDOB" in memory order */
struct sb_midi_out_record {
    u32 marker;
    u32 queued;         /* messages queued */
    u32 merged;         /* messages that replaced a waiting one */
    u32 dropped;        /* messages the policy dropped (queue full) */
    u32 offs_dropped;   /* note offs dropped because their note on was */
    u32 offs_lost;      /* note offs dropped: the queue held only note offs */
    u32 waiting_max;    /* the most messages waiting at once */
    u32 messages;       /* messages handed to the wire */
    u32 bytes;          /* bytes handed to the wire */
    u32 running;        /* status bytes left out (running status) */
    u32 transfers;      /* transfers started */
    u32 polls_busy;     /* polls that found a transfer still running */
    u32 thru;           /* messages MIDI thru passed on */
    u32 thru_sysex;     /* System Exclusive messages thru did not pass on */
    u32 panel_notes;    /* note ons the panel sent */
    u32 panel_ccs;      /* control changes the panel's knobs sent */
    u32 panel_programs; /* program changes the panel sent */
    u32 last_note_tick; /* sb_ticks() when the panel's last note on was queued */
    u32 last_start_tick;/* sb_ticks() when the last transfer started */
};
extern volatile struct sb_midi_out_record sb_midi_out;

#endif
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * MIDI out (M6b): the queue, its policy, running status and the
 * transmitter, UART1's transmit DMA (HW-73, HW-74), written from the MIDI
 * 1.0 specification's wire format and running status rules (PROVENANCE
 * P-43) and docs/DESIGN-NOTES.md, M6b. What the engine sends is in
 * fm_play.c.
 */

#include "midi_out.h"
#include "WL82.h"

volatile struct sb_midi_out_record sb_midi_out __attribute__((section(".beacon.midiout")));

/* UART1's CON0 (HW-69, HW-70, HW-73): every write keeps the UART and the
 * receive DMA on (midi.c's receiver); bit 13 written as 1 clears the
 * transmit pending, bit 15, set when a transfer's last byte has gone. */
#define UART_ON         (1u << 0)
#define UART_RX_DMA     (1u << 6)
#define UART_TX_CLEAR   (1u << 13)
#define UART_TX_PENDING (1u << 15)

/* The queue: written at head, sent from tail; one context only. */
static struct midi_msg queue[MIDI_OUT_QUEUE];
static u32 head, tail;

/* The transfer on the wire: its bytes stay as they are until it is done. */
static u8 tx_buf[MIDI_OUT_CHUNK + 4] __attribute__((aligned(4)));
static u32 busy, last_status;

/* Note ons the policy dropped, a bit per channel and note: their note
 * offs are dropped too. */
static u32 dropped_on[16][4];

static u32 kind(const struct midi_msg *m)
{
    return m->status & 0xF0u;
}

/* A note off, or a message that ends notes: these may use the reserve. */
static int ends_notes(const struct midi_msg *m)
{
    u32 k = kind(m);

    return k == MIDI_NOTE_OFF || (k == MIDI_NOTE_ON && !m->data[1])
        || (k == MIDI_CC && (m->data[0] == 120 || m->data[0] == 123));
}

/* A message whose latest value is all that matters: pressure, pitch bend,
 * program change, and control changes but those read in sequence (data
 * entry and the parameter numbers: 6, 38, 96 to 101) and the channel mode
 * messages (120 to 127). */
static int mergeable(const struct midi_msg *m)
{
    u32 c = m->data[0];

    switch (kind(m)) {
    case MIDI_POLY_AT:
    case MIDI_PROGRAM:
    case MIDI_CHANNEL_AT:
    case MIDI_BEND:
        return 1;
    case MIDI_CC:
        return !(c == 6 || c == 38 || (c >= 96 && c <= 101) || c >= 120);
    default:
        return 0;
    }
}

/* Puts m's value into a waiting message of the same kind, channel and
 * controller (or note), looking back from the newest over mergeable
 * messages only, so nothing moves past a note or a mode message. */
static int merge(const struct midi_msg *m)
{
    u32 i = head;

    while (i != tail) {
        struct midi_msg *w = &queue[--i % MIDI_OUT_QUEUE];
        if (w->status == m->status && (m->length == 1 || kind(m) == MIDI_BEND || w->data[0] == m->data[0])) {
            w->data[0] = m->data[0];
            w->data[1] = m->data[1];
            sb_midi_out.merged++;
            return 1;
        }
        if (!mergeable(w))
            break;
    }
    return 0;
}

/* Makes room for a note off in a full queue: the newest waiting message
 * that ends no notes is dropped (a note on so dropped has its note off
 * dropped too). 0 if every waiting message ends notes. */
static int evict(void)
{
    u32 i = head;

    while (i != tail) {
        struct midi_msg *w = &queue[--i % MIDI_OUT_QUEUE];
        if (!ends_notes(w)) {
            if (kind(w) == MIDI_NOTE_ON)
                dropped_on[w->status & 0x0Fu][w->data[0] >> 5] |= 1u << (w->data[0] & 31);
            for (; i + 1 != head; i++)
                queue[i % MIDI_OUT_QUEUE] = queue[(i + 1) % MIDI_OUT_QUEUE];
            head--;
            sb_midi_out.dropped++;
            return 1;
        }
    }
    return 0;
}

/* A note off whose note on was dropped: dropped as well. */
static int off_of_dropped(u32 *bits, u32 note, u32 bit)
{
    if (!(bits[note >> 5] & bit))
        return 0;
    bits[note >> 5] &= ~bit;
    sb_midi_out.offs_dropped++;
    return 1;
}

int midi_out_send(const struct midi_msg *m)
{
    u32 k = kind(m), ch = m->status & 0x0Fu, note = m->data[0] & 0x7Fu;
    u32 *bits = dropped_on[ch], bit = 1u << (note & 31), off, waiting;

    off = k == MIDI_NOTE_OFF || (k == MIDI_NOTE_ON && !m->data[1]);
    if (off && off_of_dropped(bits, note, bit))
        return 0;
    if (mergeable(m) && merge(m))
        return 1;
    waiting = head - tail;
    if (!ends_notes(m) && waiting >= MIDI_OUT_QUEUE - MIDI_OUT_RESERVE) {
        sb_midi_out.dropped++;
        if (k == MIDI_NOTE_ON)
            bits[note >> 5] |= bit;
        return 0;
    }
    if (waiting >= MIDI_OUT_QUEUE) {
        if (!evict()) {
            sb_midi_out.offs_lost++;
            return 0;
        }
        /* The message dropped may have been this note off's note on. */
        if (off && off_of_dropped(bits, note, bit))
            return 0;
        waiting--;
    }
    if (k == MIDI_NOTE_ON)
        bits[note >> 5] &= ~bit;
    queue[head % MIDI_OUT_QUEUE] = *m;
    head++;
    sb_midi_out.queued++;
    if (waiting + 1 > sb_midi_out.waiting_max)
        sb_midi_out.waiting_max = waiting + 1;
    return 1;
}

int midi_out_channel(u32 k, u32 d1, u32 d2)
{
    struct midi_msg m;

    m.status = (u8)(k | ((midi_settings.out_channel - 1u) & 0x0Fu));
    m.data[0] = (u8)(d1 & 0x7Fu);
    m.data[1] = (u8)(d2 & 0x7Fu);
    m.length = k == MIDI_PROGRAM || k == MIDI_CHANNEL_AT ? 1 : 2;
    return midi_out_send(&m);
}

void midi_out_poll(void)
{
    u32 n = 0;

    if (busy) {
        if (!(JL_UART1->CON0 & UART_TX_PENDING)) {
            sb_midi_out.polls_busy++;
            return;
        }
        JL_UART1->CON0 = UART_ON | UART_RX_DMA | UART_TX_CLEAR;
        busy = 0;
    }
    if (tail == head) {
        last_status = 0;           /* the wire has gone quiet */
        return;
    }
    /* Whole messages, up to MIDI_OUT_CHUNK bytes. */
    while (tail != head) {
        const struct midi_msg *m = &queue[tail % MIDI_OUT_QUEUE];
        u32 st = m->status, run = st < 0xF0u && st == last_status, i;

        if (n + m->length + !run > MIDI_OUT_CHUNK)
            break;
        if (run)
            sb_midi_out.running++;
        else
            tx_buf[n++] = (u8)st;
        for (i = 0; i < m->length; i++)
            tx_buf[n++] = m->data[i] & 0x7Fu;
        if (st < 0xF0u)
            last_status = st;
        else if (st < 0xF8u)
            last_status = 0;       /* system common */
        tail++;
        sb_midi_out.messages++;
    }
    JL_UART1->TXADR = (u32)tx_buf;
    JL_UART1->TXCNT = n;           /* last: it starts the transfer (HW-73) */
    busy = 1;
    sb_midi_out.transfers++;
    sb_midi_out.bytes += n;
    sb_midi_out.last_start_tick = sb_ticks();
}

