int midi_parse(u8 b, struct midi_msg *m)
{
    sb_midi.parsed++;
    if (b >= 0xF8u) {
        /* Realtime: anywhere, a message of its own; F9 and FD are
         * undefined. Nothing else changes, except at a reset. */
        if (b == 0xF9u || b == 0xFDu) {
            sb_midi.undefined++;
            return 0;
        }
        m->status = b;
        m->data[0] = m->data[1] = 0;
        m->length = 0;
        sb_midi.realtime++;
        log_msg(m);
        if (b == MIDI_RESET) {
            if (sysex && sysex_tap)
                sysex_tap(MIDI_SYSEX_CUT, b);
            end_pending();
            midi_parser_reset();
        }
        return 1;
    }
    if (b >= 0x80u) {
        u8 n = data_bytes(b);
        int done = 0;

        if (sysex && sysex_tap)
            sysex_tap(b == MIDI_EOX ? MIDI_SYSEX_END : MIDI_SYSEX_CUT, b);
        if (b == MIDI_EOX && sysex) {
            /* The end of a SysEx: handed on with its length (7 bits a
             * byte, capped), for the log only. */
            m->status = MIDI_SYSEX;
            m->data[0] = (u8)(sysex_len & 0x7Fu);
            m->data[1] = (u8)(sysex_len >> 7 > 0x7Fu ? 0x7Fu : sysex_len >> 7);
            m->length = 2;
            sysex = 0;
            log_msg(m);
            done = 1;
        } else {
            end_pending();
        }
        /* Every status but realtime ends running status; a channel
         * status starts it again. */
        status = 0;
        need = 0;
        if (b == MIDI_SYSEX) {
            sysex = 1;
            sysex_len = 0;
            sb_midi.sysex++;

