import store as st
def scenario(base, size, rounds):
    s = st.Store(); rnd = random.Random(size)
    try:
        if base:
            for i in range(16): s.put(st.PATCH, i, 2, bytes([i]) * 112)
            s.put(st.SELECTION, 0, 1, b"\x05\0\0\0"); s.put(st.SETTINGS, 0, 4, bytes(42))
        for r in range(rounds):
            data = bytes(rnd.randrange(256) for _ in range(size))
            s.put_fw(0x80, 0, 1, data)
            if base:
                for j in range(r % 4):
