import hashlib,re
hits={}
for l in open('~/.claude/jobs/cd816ac2/tmp/art/sep.log'):
    if l.startswith('HIT'):
        path,line=l.split()[1].rsplit(':',1); h=l.split('term ')[1].split()[0]
        hits.setdefault((path,int(line)),set()).add(h)
