    try: text=open(path).read().splitlines()[line-1]
    except Exception as e: print(path,line,'?'); continue
    for w in set(re.findall(r'(?<![0-9A-Za-z_])[A-Za-z_][A-Za-z0-9_]*', text))|set(re.findall(r'0[xX][0-9A-Fa-f_]{4,}',text)):
        for cand in (w, "0x%x" % int(w,16) if w.lower().startswith('0x') else w):
            if hashlib.sha256(cand.encode()).hexdigest()[:16] in hs: print(path,line,'->',cand)
